// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { realndarray, complexndarray, genericndarray } from '@stdlib/types/ndarray';

/**
* Input array.
*/
type InputArray = realndarray | genericndarray<number>;

/**
* Interface defining options.
*/
interface Options {
	/**
	* Number of points over which to compute the transform.
	*/
	n?: number;

	/**
	* Normalization mode.
	*/
	normalize?: 'backward' | 'ortho' | 'forward';
}

/**
* Interface for computing the forward real FFT.
*/
interface Rfftf {
	/**
	* Returns a new ndarray containing the one-dimensional discrete Fourier transform of a real-valued input ndarray.
	*
	* @param x - input ndarray
	* @param options - function options
	* @returns output ndarray
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var ndarray = require( '@stdlib/ndarray/ctor' );
	*
	* // Create a data buffer:
	* var xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	*
	* // Define the shape of the input array:
	* var sh = [ 4 ];
	*
	* // Define the array strides:
	* var sx = [ 1 ];
	*
	* // Define the index offset:
	* var ox = 0;
	*
	* // Create an input ndarray:
	* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
	*
	* // Perform operation:
	* var out = rfftf( x );
	* // returns <ndarray>[ <Complex128>[ 10.0, 0.0 ], <Complex128>[ -2.0, 2.0 ], <Complex128>[ -2.0, 0.0 ] ]
	*/
	( x: InputArray, options?: Options ): complexndarray;

	/**
	* Computes the one-dimensional discrete Fourier transform of a real-valued input ndarray and assigns the results to a provided output ndarray.
	*
	* @param x - input ndarray
	* @param out - output ndarray
	* @param options - function options
	* @returns output ndarray
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var ndarray = require( '@stdlib/ndarray/ctor' );
	* var zeros = require( '@stdlib/ndarray/zeros' );
	*
	* // Create a data buffer:
	* var xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	*
	* // Define the shape of the input array:
	* var sh = [ 4 ];
	*
	* // Define the array strides:
	* var sx = [ 1 ];
	*
	* // Define the index offset:
	* var ox = 0;
	*
	* // Create an input ndarray:
	* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
	*
	* // Create an output ndarray:
	* var out = zeros( [ 3 ], { 'dtype': 'complex128' } );
	*
	* // Perform operation:
	* var v = rfftf.assign( x, out );
	* // returns <ndarray>[ <Complex128>[ 10.0, 0.0 ], <Complex128>[ -2.0, 2.0 ], <Complex128>[ -2.0, 0.0 ] ]
	*
	* var bool = ( v === out );
	* // returns true
	*/
	assign<T extends complexndarray>( x: InputArray, out: T, options?: Options ): T;
}

/**
* Returns a new ndarray containing the one-dimensional discrete Fourier transform of a real-valued input ndarray.
*
* @param x - input ndarray
* @param options - function options
* @returns output ndarray
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray = require( '@stdlib/ndarray/ctor' );
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 4 ];
*
* // Define the array strides:
* var sx = [ 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Perform operation:
* var out = rfftf( x );
* // returns <ndarray>[ <Complex128>[ 10.0, 0.0 ], <Complex128>[ -2.0, 2.0 ], <Complex128>[ -2.0, 0.0 ] ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray = require( '@stdlib/ndarray/ctor' );
* var zeros = require( '@stdlib/ndarray/zeros' );
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 4 ];
*
* // Define the array strides:
* var sx = [ 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Create an output ndarray:
* var out = zeros( [ 3 ], { 'dtype': 'complex128' } );
*
* // Perform operation:
* var v = rfftf.assign( x, out );
* // returns <ndarray>[ <Complex128>[ 10.0, 0.0 ], <Complex128>[ -2.0, 2.0 ], <Complex128>[ -2.0, 0.0 ] ]
*
* var bool = ( v === out );
* // returns true
*/
declare const rfftf: Rfftf;


// EXPORTS //

export = rfftf;
